using Quill.Windows;
using Xunit;
namespace Quill.Windows.Tests;
public sealed class FakeAudio : IAudioRecorder {
 public event Action<double,long>? Level; public event Action? AutoStop; public bool Recording { get; private set; } public int Starts { get; private set; }
 public void Start(QuillSettings settings,bool microphoneTest = false) { Recording = true; Starts++; Level?.Invoke(1000,0); }
 public Task<AudioTake> Stop() { Recording = false; return Task.FromResult(new AudioTake(AudioRecorder.Wav(new byte[32000]),1000)); }
 public void EndAutomatically() => AutoStop?.Invoke(); public void Dispose() { Recording = false; }
}
public sealed class FakeInjector : ITextInjector { public bool Sensitive { get; set; } public bool Accepted { get; set; } = true; public bool Editable { get; set; } = true; public Action? OnInsert { get; set; } public string Text { get; private set; } = ""; public string Application { get; set; } = "test-editor"; public Task<FocusTarget> Capture() => Task.FromResult(new FocusTarget(12,[3,2],Application,Editable,Sensitive)); public Task<bool> Insert(FocusTarget target,string text) { Text = text; OnInsert?.Invoke(); return Task.FromResult(Accepted); } public Task<bool> CanType() => Task.FromResult(!Sensitive); }
public sealed class FakeClipboard : IClipboardService { public string Text { get; private set; } = ""; public bool Transient { get; private set; } public bool Copy(string text,bool transient = true) { Text = text; Transient = transient; return true; } public Task<bool> Paste(string text,ITextInjector injector) => Task.FromResult(true); }
public sealed class PipelineFixture : IDisposable {
 public TestFolder Folder { get; } = new(); public SettingsStore Settings { get; } public SecretStore Secrets { get; } public HistoryStore History { get; } public FakeAudio Audio { get; } = new(); public FakeInjector Injector { get; } = new(); public FakeClipboard Clipboard { get; } = new(); public DictationController Controller { get; }
 public PipelineFixture(Func<HttpRequestMessage,CancellationToken,Task<HttpResponseMessage>> response) { Settings = new(Folder.Path); Settings.Value.OnboardingComplete = true; Settings.Value.InjectionConsent = true; Settings.Value.CleanupEnabled = false; Secrets = new(Folder.Path); Secrets.Add(Provider.Groq,"fixture-provider-key","fixture"); History = new(Folder.Path); Controller = new(Settings,Secrets,History,new ProviderClient(new MockHttp(response)),Audio,Injector,Clipboard,Folder.Path); }
 public void Dispose() { Controller.Dispose(); Folder.Dispose(); }
}
public sealed class PipelineTests {
 [Fact] public async Task NoEditableFieldBlocksOrdinaryCaptureButAllowsExplicitClipboardDictation() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"clipboard words\"}"))); f.Injector.Editable = false; await f.Controller.Toggle(); Assert.Equal(0,f.Audio.Starts); Assert.Equal("focus_to_paste",f.Controller.Error); await f.Controller.Cancel(); await f.Controller.DictateToClipboard(); await f.Controller.StopRecording(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Equal("clipboard words",f.Clipboard.Text); Assert.False(f.Clipboard.Transient); Assert.Empty(f.Injector.Text); }
 [Fact] public async Task LateStopCallbacksNeverRestartRecording() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"one recording\"}"))); await f.Controller.Toggle(); await f.Controller.StopRecording(); await f.Controller.StopRecording(); Assert.Equal(1,f.Audio.Starts); Assert.Equal(DictationState.Idle,f.Controller.State); }
 [Fact] public async Task PrivateRecordingStaysPrivateAcrossFailureAndRetry() { int calls = 0; using var f = new PipelineFixture((_,_) => Task.FromResult(++calls == 1 ? MockHttp.Json("{}",503) : MockHttp.Json("{\"text\":\"private retry\"}"))); f.Settings.Value.PrivateMode = true; await f.Controller.Toggle(); await f.Controller.Toggle(); f.Settings.Value.PrivateMode = false; await f.Controller.Toggle(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Empty(f.History.List(f.Settings.Value)); }
 [Fact] public async Task PrivateRecordingProvenanceSurvivesProcessRecovery() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{}",503))); f.Settings.Value.PrivateMode = true; await f.Controller.Toggle(); await f.Controller.Toggle(); f.Settings.Value.PrivateMode = false; using var recovered = new DictationController(f.Settings,f.Secrets,f.History,new ProviderClient(new MockHttp((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"private recovered\"}")))),new FakeAudio(),f.Injector,f.Clipboard,f.Folder.Path); await recovered.Toggle(); Assert.Equal(DictationState.Paste,recovered.State); Assert.Empty(f.History.List(f.Settings.Value)); }
 [Fact] public async Task TurningHistoryOffDuringRecordingPreventsHistoryWrite() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"do not save\"}"))); await f.Controller.Toggle(); f.Settings.Value.HistoryEnabled = false; await f.Controller.Toggle(); Assert.Empty(f.History.List(f.Settings.Value)); }
 [Fact] public async Task HistoryDatabaseFailureCannotMakeDeliveredAudioRetryable() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"delivered once\"}"))); using (var db = new Microsoft.Data.Sqlite.SqliteConnection("Pooling=False;Data Source=" + Path.Combine(f.Folder.Path,"history.sqlite3"))) { db.Open(); using var command = db.CreateCommand(); command.CommandText = "DROP TABLE transcripts"; command.ExecuteNonQuery(); } await f.Controller.Toggle(); await f.Controller.Toggle(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Equal("delivered once",f.Injector.Text); Assert.Empty(Directory.GetFiles(f.Folder.Path,"pending*")); await f.Controller.StopRecording(); Assert.Equal(1,f.Audio.Starts); }
 [Fact] public async Task RetiredFileDeletionFailureDoesNotOfferDeliveredRecordingAgain() { int calls = 0; using var f = new PipelineFixture((_,_) => Task.FromResult(++calls == 1 ? MockHttp.Json("{}",503) : MockHttp.Json("{\"text\":\"delivered once\"}"))); await f.Controller.Toggle(); await f.Controller.Toggle(); var retired = Path.Combine(f.Folder.Path,"pending-audio.dpapi.consumed"); f.Injector.OnInsert = () => File.SetAttributes(retired,FileAttributes.ReadOnly); try { await f.Controller.Toggle(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.False(File.Exists(Path.Combine(f.Folder.Path,"pending-audio.dpapi"))); Assert.True(File.Exists(retired)); using var recovered = new DictationController(f.Settings,f.Secrets,f.History,new ProviderClient(new MockHttp((_,_) => throw new InvalidOperationException())),new FakeAudio(),f.Injector,f.Clipboard,f.Folder.Path); Assert.Equal(DictationState.Idle,recovered.State); } finally { if (File.Exists(retired)) File.SetAttributes(retired,FileAttributes.Normal); } }
 [Fact] public async Task EndToEndCaptureTranscribeWordsInsertAndHistory() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"hello quell\"}"))); f.Settings.Value.CustomWords.Add(new("quell","Quill")); await f.Controller.Toggle(); Assert.Equal(DictationState.Recording,f.Controller.State); await f.Controller.Toggle(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Equal("hello Quill",f.Injector.Text); Assert.Single(f.History.List(f.Settings.Value)); Assert.Empty(Directory.GetFiles(f.Folder.Path,"pending*")); }
 [Fact] public async Task UnverifiedInsertionOffersClipboardAndNeverLosesTranscript() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"recover these words\"}"))); f.Injector.Accepted = false; await f.Controller.Toggle(); await f.Controller.Toggle(); Assert.Equal(DictationState.Paste,f.Controller.State); Assert.Equal("recover these words",f.Clipboard.Text); Assert.Equal("FALLBACK_PASTE",f.History.List(f.Settings.Value)[0].Status); }
 [Fact] public async Task SensitiveFieldsAreBlockedBeforeMicStarts() { using var f = new PipelineFixture((_,_) => throw new InvalidOperationException()); f.Injector.Sensitive = true; await f.Controller.Toggle(); Assert.Equal(0,f.Audio.Starts); Assert.Equal("sensitive_field",f.Controller.Error); }
 [Fact] public async Task MissingKeyBlockedBeforeMicStarts() { using var f = new PipelineFixture((_,_) => throw new InvalidOperationException()); f.Secrets.Clear(); await f.Controller.Toggle(); Assert.Equal(0,f.Audio.Starts); Assert.Equal("key_missing",f.Controller.Error); }
 [Fact] public async Task FailureRetainsEncryptedRecordingAndRetryUsesSameTake() { int calls = 0; using var f = new PipelineFixture((_,_) => Task.FromResult(++calls == 1 ? MockHttp.Json("{}",503) : MockHttp.Json("{\"text\":\"retried words\"}"))); await f.Controller.Toggle(); await f.Controller.Toggle(); Assert.Equal(DictationState.Error,f.Controller.State); var path = Path.Combine(f.Folder.Path,"pending-audio.dpapi"); Assert.True(File.Exists(path)); Assert.NotEqual("RIFF",System.Text.Encoding.ASCII.GetString(File.ReadAllBytes(path),0,4)); await f.Controller.Toggle(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Equal(1,f.Audio.Starts); Assert.Equal(2,calls); Assert.False(File.Exists(path)); }
 [Fact] public async Task DiscardDeletesPendingAndClearsTranscript() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{}",503))); await f.Controller.Toggle(); await f.Controller.Toggle(); await f.Controller.Cancel(); Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Empty(f.Controller.LastText); Assert.Empty(Directory.GetFiles(f.Folder.Path,"pending*")); }
 [Fact] public async Task PrivateModeAtStartOrAtCompletionPreventsHistory() { using var f = new PipelineFixture((_,_) => Task.FromResult(MockHttp.Json("{\"text\":\"private words\"}"))); f.Settings.Value.PrivateMode = true; await f.Controller.Toggle(); f.Settings.Value.PrivateMode = false; await f.Controller.Toggle(); Assert.Empty(f.History.List(f.Settings.Value)); await f.Controller.Toggle(); f.Settings.Value.PrivateMode = true; await f.Controller.Toggle(); Assert.Empty(f.History.List(f.Settings.Value)); }
 [Fact] public async Task CancelDuringNetworkPreventsLateInsertAndHistory() { var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); using var f = new PipelineFixture(async (_,token) => { entered.SetResult(); await Task.Delay(Timeout.Infinite,token); return MockHttp.Json("{\"text\":\"never insert\"}"); }); await f.Controller.Toggle(); var stop = f.Controller.Toggle(); await entered.Task; await f.Controller.Cancel(); await stop; Assert.Equal(DictationState.Idle,f.Controller.State); Assert.Empty(f.Injector.Text); Assert.Empty(f.History.List(f.Settings.Value)); }
 [Fact] public async Task RepeatedToggleDuringRequestCannotStartSecondRecording() { var entered = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); var finish = new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously); using var f = new PipelineFixture(async (_,_) => { entered.SetResult(); await finish.Task; return MockHttp.Json("{\"text\":\"once\"}"); }); await f.Controller.Toggle(); var stop = f.Controller.Toggle(); await entered.Task; await f.Controller.Toggle(); Assert.Equal(1,f.Audio.Starts); finish.SetResult(); await stop; Assert.Single(f.History.List(f.Settings.Value)); }
}
